ex-empty-avg.code:
text = ''
total = 0
count = 0
for character in text:
    total = total + int(character)
    count = count + 1
if count > 0:
    print(f'Average: {total / count:.2f}')
else:
    print('No values to average.')

ex-digits.code:
text = 'Room 201 opens at 9'.lower()
digits = 0
for character in text:
    if character.isdigit():
        digits = digits + 1
print('Digit characters:', digits)

ex-matches.code:
word = 'mississippi'
matches = 0
for character in word:
    if character == 's':
        matches = matches + 1
print(matches)

ex-first-pass.code:
word = 'LOOP'
first = True
for character in word:
    if first:
        print(character, end='')
        first = False
    else:
        print(', ', character, sep='', end='')
print()
